 "content": "from collections import Counter


def transform(grid):
    """Encode each non-background horizontal bar by its color, in descending color order."""
    counts = Counter()
    for row in grid:
        previous = None
        for value in row:
            if value != 0 and value != previous:
                counts[value] += 1
            previous = value
    # The background is the most frequent cell color; the remaining colors are bars.
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    counts.pop(background, None)
    encoded = []
    for color in sorted(counts, reverse=True):
        encoded.extend([color] * counts[color])
    encoded = (encoded + [0] * 6)[:6]
    return [encoded[:3], encoded[3:]]
